// The shape of a generated scale document, as a pure function (no Node
// imports), so `bench/generate.js` can write n50/n500/n2000 with it and a
// test — under Node or in a browser — can build any other size in memory
// (Stage K: DD-06 §8's 1 000-node conformance graph) without it being one
// more generated file in `corpus/`.

/**
 * A flat scale fixture: `n` nodes in a chain (`n0 -> n1 -> n2 -> ...`), grouped
 * into containers of 10 so a scale document also exercises nesting rather than
 * one 2 000-wide root. Every 7th node carries a label with a multi-word string,
 * so measurement is exercised too, not just node/edge count.
 *
 * `{ rich: true }` (A18, DD-11 T56, T57) is the markdown variant: **every** node
 * carries a rich label, ``**Node** `n${i}` ``, and every tenth has `@size.maxWidth: 90`,
 * so it wraps. It is built in memory by the benches that report it (not
 * written to `corpus/`, and not gated): the gated n50/n500/n2000 hold no markup.
 *
 * `{ labelled: true }` (fix round 1, item 9) is its control: the same labels,
 * `Node n${i}`, on every node, and the same `@size.maxWidth` on every tenth,
 * with no markup, so T57 can tell the cost of the run tspans from the cost of
 * having every node labelled.
 *
 * `{ boxes: 'grid' | 'elk' }` (B8, DD-14 C49, §8.2) gives every container
 * that engine of its own (`@layout.engine`), so the bench can time a
 * document of `n / 10` boxes under any root engine, which the caller picks.
 */
export function scaleDocument(n, { rich = false, labelled = false, boxes = undefined } = {}) {
  const perContainer = 10;
  const kind = `${rich ? ' rich' : labelled ? ' labelled' : ''}${boxes === undefined ? '' : ` ${boxes} boxes`}`;
  const lines = [`// Generated by bench/generate.js — ${n} nodes${kind}. Do not hand-edit.`, `@title: "Scale ${n}${kind}"`, ''];

  const containerCount = Math.ceil(n / perContainer);
  let nodeIndex = 0;
  for (let c = 0; c < containerCount; c += 1) {
    lines.push(`g${c}: {`);
    if (boxes !== undefined) lines.push(`  @layout.engine: ${boxes}`);
    const inThisContainer = Math.min(perContainer, n - nodeIndex);
    for (let i = 0; i < inThisContainer; i += 1) {
      const box = nodeIndex % 10 === 0 ? ', @size: { maxWidth: 90 }' : '';
      const label = rich
        ? ` { @label: "**Node** \`n${nodeIndex}\`"${box} }`
        : labelled
        ? ` { @label: "Node n${nodeIndex}"${box} }`
        : nodeIndex % 7 === 0 ? ` { @label: "Node number ${nodeIndex}" }` : ' {}';
      lines.push(`  n${nodeIndex}:${label}`);
      nodeIndex += 1;
    }
    lines.push('}');
  }

  lines.push('');
  for (let i = 0; i < n - 1; i += 1) {
    lines.push(`g${Math.floor(i / perContainer)}.n${i} -> g${Math.floor((i + 1) / perContainer)}.n${i + 1}`);
  }
  lines.push('');
  return lines.join('\n');
}

/**
 * One edit to a `scaleDocument(n, { boxes })` source, for the keystroke bench
 * of the per-box layout cache (`perf/b8-cache`, DD-14 C32):
 *
 * - `'inside'`: a new node in container `g${k}`, so that one box changes;
 * - `'outside'`: a new top-level node before every container, so no box's
 *   content changes but every source span after it moves;
 * - `'options'`: an engine option on `g${k}`'s own `@layout` (`elk`'s
 *   `direction: right`, `grid`'s `columns: 3`), so that box's options change.
 */
export function editScaleDocument(source, kind, k) {
  const open = new RegExp(`^g${k}: \\{\\n  @layout\\.engine: (\\w+)$`, 'm');
  const match = open.exec(source);
  if (kind === 'outside') return source.replace(/^(@title: .*\n)/m, `$1top${k}: { @label: "Top ${k}" }\n`);
  if (match === null) throw new Error(`editScaleDocument: no box g${k}`);
  if (kind === 'inside') return source.replace(open, `${match[0]}\n  extra${k}: { @label: "Extra ${k}" }`);
  if (kind === 'options') return source.replace(open, `${match[0]}\n  @layout.${match[1] === 'grid' ? 'columns: 3' : 'direction: right'}`);
  throw new Error(`editScaleDocument: unknown kind ${kind}`);
}
